  "faits": "Faits non vérifiés (l'arrêt du 2 mars 1915 est absent de Légifrance et aucune source secondaire accessible n'a pu être consultée) ; l'arrêt est classiquement cité comme celui qui affirme le caractère subsidiaire de l'action de in rem verso, après l'arrêt Boudier (Req. 15 juin 1892) qui l'avait admise.",
  "question": "L'appauvri qui dispose d'une autre action peut-il exercer l'action de in rem verso ?",
  "solution": "Selon la présentation classique de la doctrine, l'action de in rem verso est subsidiaire : elle est fermée à l'appauvri qui dispose d'une autre action (contrat, responsabilité...). Règle aujourd'hui codifiée à l'art. 1303-3 C. civ. (ordonnance du 10 février 2016) : l'appauvri n'a pas d'action sur ce fondement lorsqu'une autre action lui est ouverte ou se heurte à un obstacle de droit, tel que la prescription. Texte exact de l'arrêt non vérifié.",
  "justifie": [
   {
    "argument": "Refuser l'action fondée sur l'enrichissement injustifié au demandeur qui disposait d'une autre action (contractuelle, délictuelle...), même si elle est prescrite : la subsidiarité, d'origine jurisprudentielle, est reprise à l'art. 1303-3.",
    "ou": "Cas pratique : test de subsidiarité de l'enrichissement injustifié."
   },
   {
    "argument": "Retracer l'évolution de l'enrichissement sans cause : admission (Boudier, 1892), encadrement par la subsidiarité (1915), puis codification en 2016 (art. 1303 s.).",
    "ou": "Dissertation sur l'histoire de l'enrichissement sans cause."
   }
  ],
  "distinguer": "Ne pas confondre avec l'arrêt Boudier (Req. 15 juin 1892), qui a consacré l'action de in rem verso. À ne pas confondre non plus la subsidiarité avec la simple absence des conditions d'une autre action : l'art. 1303-3 écarte l'action lorsque l'autre action existe ou se heurte à un obstacle de droit comme la prescription, mais l'échec de l'autre action pour défaut de preuve n'ouvre pas le in rem verso. La jurisprudence antérieure à 2016 avait nuancé la règle ; à vérifier avant de citer un arrêt précis d'assouplissement.",
