  "faits": "Un propriétaire (Coquerel) installe sur son terrain, contigu à celui de l'industriel Clément-Bayard, des carcasses de bois de seize mètres de haut surmontées de tiges de fer pointues, sans aucune utilité pour son fonds et dans le seul but de nuire. Un ballon dirigeable de Clément-Bayard est endommagé. La cour d'appel d'Amiens (12 nov. 1913) condamne le propriétaire à réparer et ordonne l'enlèvement des tiges de fer, mais refuse de faire détruire le reste du dispositif, faute de preuve qu'il ait causé ou doive causer un dommage.",
  "question": "L'exercice du droit de propriété peut-il constituer une faute lorsqu'il est dénué d'utilité et animé de la seule intention de nuire ?",
  "solution": "Rejet de la requête. La Chambre des requêtes valide l'arrêt d'Amiens : le dispositif, inutile pour son auteur, n'avait été érigé que pour nuire et, vu sa hauteur, ne constituait pas la clôture que l'art. 647 permet d'établir pour protéger ses intérêts légitimes ; les juges ont pu y voir un abus du droit de propriété, condamner à réparer le dommage et ordonner l'enlèvement des tiges. Le refus de détruire le surplus du dispositif, dont le caractère dommageable n'était pas démontré, est également approuvé.",
